"use client";
import { useState } from "react";
export default function AdminAnnouncementForm() { const [form, setForm] = useState({ title: "", body: "", channel: "IN_APP", status: "DRAFT" }); const [notice, setNotice] = useState(""); async function submit() { const response = await fetch("/api/admin/announcements", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(form) }); const data = await response.json(); setNotice(response.ok ? "Announcement saved." : data.error || "Unable to save announcement."); if (response.ok) setForm({ title: "", body: "", channel: "IN_APP", status: "DRAFT" }); } return <div className="rounded-2xl border border-slate-800 bg-slate-900 p-5 shadow-xl"><h2 className="text-base font-semibold text-white">Publish announcement</h2><p className="mt-1 text-xs text-slate-400">In-app publishing is live. External channels remain connector-ready demo controls.</p><div className="mt-5 space-y-3"><input value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} placeholder="Announcement title" className="w-full rounded-xl border border-slate-800 bg-slate-950 px-4 py-3 text-sm text-white outline-none focus:border-red-400" /><textarea value={form.body} onChange={(e) => setForm({ ...form, body: e.target.value })} placeholder="Message" rows={4} className="w-full rounded-xl border border-slate-800 bg-slate-950 px-4 py-3 text-sm text-white outline-none focus:border-red-400" /><div className="flex gap-3"><select value={form.channel} onChange={(e) => setForm({ ...form, channel: e.target.value })} className="rounded-lg border border-slate-800 bg-slate-950 px-3 py-2 text-xs text-slate-300"><option value="IN_APP">In-app</option><option value="EMAIL">Email connector</option><option value="SOCIAL">Social connector</option></select><select value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })} className="rounded-lg border border-slate-800 bg-slate-950 px-3 py-2 text-xs text-slate-300"><option>DRAFT</option><option>PUBLISHED</option></select><button onClick={submit} className="ml-auto rounded-lg bg-red-500 px-4 py-2 text-xs font-semibold text-white">Save announcement</button></div>{notice && <p className="text-xs text-slate-400">{notice}</p>}</div></div>; }